const ICONS={book:'<path d="M3 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-3H3zm18 0h-6a3 3 0 0 0-3 3v14a4 4 0 0 1 4-3h5z"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',note:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6M9 12h6M9 16h4"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m15 9-2 4-4 2 2-4z"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 4v3"/>',layers:'<path d="m3 8 9-5 9 5-9 5zm0 5 9 5 9-5M3 18l9 5 9-5"/>',check:'<path d="m5 12 4 4L19 6"/>',spark:'<path d="M12 3v4m0 10v4M3 12h4m10 0h4M5.5 5.5l3 3m7 7 3 3M5.5 18.5l3-3m7-7 3-3"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4m0 3h.01"/>'};
const icon=n=>`<svg class="ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[n]||ICONS.book}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STEPS=['观察','判断','下注','揭晓','比较','解释'];
const STORE='country-causal-lab-v1';let indicators={},storageOK=true,view='lab';
const blank=()=>({round:0,step:0,picks:[null,null,null],growth:4,confidence:70,risk:null,thesis:'',reflection:'',records:[],complete:false});
let state={country:'KOR',countries:{KOR:blank(),SGP:blank(),ARG:blank()}};
try{const old=JSON.parse(localStorage.getItem(STORE));if(old&&COUNTRIES[old.country]&&old.countries&&Object.keys(COUNTRIES).every(k=>old.countries[k]&&Array.isArray(old.countries[k].records)&&old.countries[k].round>=0&&old.countries[k].round<3&&old.countries[k].step>=0&&old.countries[k].step<=5))state=old;}catch(e){storageOK=false;}
const session=()=>state.countries[state.country], country=()=>COUNTRIES[state.country], round=()=>country().rounds[session().round];
function save(){try{localStorage.setItem(STORE,JSON.stringify(state));}catch(e){storageOK=false;}}
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3000);}
function num(n){return Math.round(n).toLocaleString('en-US');}
function actualGrowth(){const d=indicators[state.country].gdp,y=round().year;return (Math.pow(d[y+10]/d[y],.1)-1)*100;}
function record(){return session().records.find(r=>r.year===round().year);}
function navigate(v){view=v;render(true);}
function setStep(n){if(n<0||n>5)return;if(n>=3&&!record())return;session().step=n;save();render(true);}
function header(){const c=country(),s=session(),r=round();return `<aside class="sidebar"><div class="brand"><svg class="brand-mark" viewBox="0 0 36 36" fill="none" aria-hidden="true"><path d="M4 28V16h7v12m4 0V7h7v21m4 0V20h6v8" stroke="currentColor" stroke-width="2.5"/><path d="M3 32h30" stroke="currentColor"/></svg><div><strong>国家发展实验室</strong><small>THE DEVELOPMENT LAB</small></div></div><nav class="nav" aria-label="主导航">${[['lab','globe','历史实验'],['notebook','note','判断手记'],['method','compass','如何理解因果']].map(([v,i,t])=>`<button data-nav="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}>${icon(i)}${t}</button>`).join('')}</nav><div class="side-label">当前档案 / ${c.name}</div><div class="journey">${c.rounds.map((r,i)=>`<div class="journey-item ${i===s.round?'current':''} ${i<s.round||s.complete?'done':''}"><span class="node"></span><div>${r.year}—${r.year+10}<small>${i<s.round||s.complete?'已留下判断':i===s.round?'正在探索':'历史尚未揭晓'}</small></div></div>`).join('')}</div><div class="side-bottom">${icon('book')} 理解选择背后的条件<p>历史只有一次。<br>解释，始终可以被追问。</p><button class="text-btn" style="color:#a8bbd4;font-size:12px" data-action="countries">切换国家档案</button></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb"><span>历史实验</span><span>/</span><strong>${c.name}</strong><span>/</span><span>${r.year} 年</span></div><div class="top-actions"><span class="status">${storageOK?'进度保存在本机':'当前进度仅在本页'}</span><button class="text-btn" data-action="countries">切换国家</button><button class="text-btn" data-nav="method" aria-label="使用说明">${icon('help')}</button></div></header><main id="main" tabindex="-1" class="main-focus">`;}
function steps(){return `<div class="steps" aria-label="学习回合进度">${STEPS.map((t,i)=>`<div class="step ${i===session().step?'active':i<session().step?'complete':''}" ${i===session().step?'aria-current="step"':''}><b>${i<session().step?'✓':i+1}</b>${t}</div>`).join('')}</div>`;}
function roundHeading(){const r=round();return `<div class="round-heading"><div><div class="eyebrow"><span>第 ${session().round+1} / 3 回合</span> ${country().name} · ${country().region}</div><h1>${session().step===0?`${r.year}，站在历史的起点。`:['','为下一个十年，做出选择。','在答案揭晓前，留下判断。','现在，让历史打开档案。','把你的预期，放在历史旁边。','结果之后，继续追问原因。'][session().step]}</h1><p class="intro">${session().step===0?'你只知道此刻的条件。未来，暂时封存。':`${r.year}—${r.year+10} 年 · ${['','每个选项都有成立条件与代价','下注的是判断，不是虚拟资金','记录事实，也看见增长之外的代价','历史吻合度不代表政策优劣','区分事实、机制与尚未解决的问题'][session().step]}`}</p></div><div class="year-stamp">${r.year}<small>决策时点</small></div></div>${steps()}`;}
function metrics(){const c=state.country,r=round(),d=indicators[c];return `<div class="metrics"><div class="metric"><div class="metric-label">人口</div><div class="metric-value">${(d.population[r.year]/1000000).toFixed(1)}<em>百万</em></div><div class="metric-note">国内市场与劳动力规模</div></div><div class="metric"><div class="metric-label">人均 GDP</div><div class="metric-value">${num(d.gdp[r.year])}<em>美元</em></div><div class="metric-note">2015 年不变价 · 非 PPP</div></div><div class="metric"><div class="metric-label">城市化率</div><div class="metric-value">${d.urban[r.year].toFixed(1)}<em>%</em></div><div class="metric-note">城市人口占总人口</div></div><div class="metric"><div class="metric-label">教育基础</div><div class="metric-value qual">${r.education}</div><div class="metric-note">${r.eduNote} · 定性</div></div></div>`;}
function dossier(){const c=country();return `<aside class="aside"><section class="dossier"><div class="dossier-head"><h2>${c.name}</h2><span class="code">${c.code} / ${round().year}</span></div><div class="map"><svg viewBox="0 0 260 172" role="img" aria-label="${c.name}地理轮廓"><path d="${indicators[c.code].map||''}" fill="#cfdaeb" stroke="#7791b4" stroke-width="1"/></svg><span class="coord">${c.coord} · 地理示意</span></div><dl class="dossier-facts"><div><dt>地理资源</dt><dd>${c.geography}</dd></div><div><dt>核心约束</dt><dd>${round().constraint}</dd></div><div><dt>资料时点</dt><dd>${round().year} 年；政治事件按该年概述</dd></div></dl><button class="context-button" data-action="context">展开完整国情档案 ${icon('layers')}</button></section><section class="locked"><strong>${icon('lock')}${round().year+10} 年的历史尚未揭晓</strong>做出选择并留下预测后，才能查看这十年真实发生了什么。</section></aside>`;}
function actionBar(text,button,action,back,disabled=false){return `<div class="bottom-action"><p>${text}</p><div>${back!==undefined?`<button class="secondary" data-step="${back}">返回${STEPS[back]}</button> `:''}<button class="primary" data-action="${action}" ${disabled?'disabled':''}>${button}</button></div></div>`;}
function observe(){const r=round(),prev=session().records.find(x=>x.year===r.year-10);return `<div class="section-line"><h2>先看四个起点</h2><small>只呈现会改变判断的信息</small></div>${metrics()}<div class="two-col"><div><section class="briefing"><div class="question-head"><div class="question-icon">${icon('compass')}</div><div><small>你面对的决策</small></div></div><h2>${r.title}</h2><p class="lead">${r.subtitle}</p><div class="evidence">${r.evidence.map(([h,p,t],i)=>`<article class="evidence-item"><span class="evidence-num">0${i+1}</span><div><h3>${h}<span class="tag">${t}</span></h3><p>${p}</p></div></article>`).join('')}</div><div class="note">先问：哪个约束最可能让你的政策失效？不是所有问题，都能同时解决。</div></section>${prev?`<div class="reason"><strong>上一轮你修正了什么</strong><p>${esc(prev.reflection)}</p><p class="small">这一轮从真实历史的新条件出发，继续检验你的判断。</p></div>`:''}${actionBar('没有标准答案。重要的是，你为什么这样选。','开始制定政策','choose')}</div>${dossier()}</div>`;}
function choose(){const s=session(),r=round();return `<div class="two-col"><div><section class="panel"><h2>先选方向，再解释取舍</h2><p>每组选择一个优先方向。选项是学习用的政策简化，现实往往是组合与调整。</p>${r.groups.map((g,i)=>`<section class="policy-group"><div class="policy-title"><span>0${i+1}</span><h3>${POLICIES[g].name}</h3><small>选择一项</small></div><div class="options" role="radiogroup" aria-label="${POLICIES[g].name}">${POLICIES[g].options.map((o,j)=>`<button class="option" data-pick="${i},${j}" role="radio" aria-checked="${s.picks[i]===j}" ${record()?'disabled':''}><span class="radio" aria-hidden="true"></span><span class="option-title">${o[0]}</span><p>${o[1]}</p><div class="cost"><strong>代价</strong> / ${o[2]}</div><div class="conditional">前提 / ${o[3]}</div></button>`).join('')}</div></section>`).join('')}</section>${actionBar(record()?'本轮已封存，可查看原始选择。':`已选择 ${s.picks.filter(x=>x!==null).length} / 3 项政策方向`,'记录预测与信心','bet',0,s.picks.includes(null))}</div><aside class="summary-box"><h3>${icon('note')} 你的政策组合</h3>${r.groups.map((g,i)=>`<div class="selected-summary"><strong>${POLICIES[g].name}</strong><p>${s.picks[i]===null?'尚未选择':POLICIES[g].options[s.picks[i]][0]}</p></div>`).join('')}<p>这些选择不会直接换算成 GDP。下一步，先记录你相信哪条因果链会成立。</p><button class="text-btn" data-action="context" style="font-size:12px;margin-top:16px">重新查看国情档案</button></aside></div>`;}
function bet(){const s=session();return `<div class="two-col"><section class="panel"><h2>十年以后，你预期会发生什么？</h2><p>先预测现实中将发生的结果。揭晓后检验你的预期，不把真实结果当作你所选政策的效果。</p><label class="input-label" for="growth">实际人均 GDP 的年均增长率</label><div class="range-value"><span id="growth-value">${Number(s.growth).toFixed(1)}%</span><small>未来十年的几何年均增长</small></div><input id="growth" type="range" min="-5" max="12" step="0.5" value="${s.growth}" ${record()?'disabled':''}><div class="range-ends"><span>−5% · 持续收缩</span><span>12% · 快速增长</span></div><p class="field-note">直觉提示：年均 4% 意味着十年后人均产出约增加 48%。</p><label class="input-label">你认为真实增长会落在预测值 ±2 个百分点内的概率？</label><div class="chips">${[50,70,90].map(n=>`<button class="chip ${s.confidence===n?'selected':''}" data-confidence="${n}" aria-pressed="${s.confidence===n}" ${record()?'disabled':''}>${n}% ${n===50?'保留判断':n===70?'比较有把握':'很有把握'}</button>`).join('')}</div><p class="field-note">用多轮记录检视是否过度自信；单次落入区间不能证明你的概率判断正确。</p><label class="input-label">你最担心的失效点</label><div class="chips">${['外汇与债务','执行能力','社会代价','外部冲击'].map(t=>`<button class="chip ${s.risk===t?'selected':''}" data-risk="${t}" aria-pressed="${s.risk===t}" ${record()?'disabled':''}>${t}</button>`).join('')}</div><label class="input-label" for="thesis">你的因果判断 <span class="small">至少 8 个字</span></label><textarea id="thesis" maxlength="1500" placeholder="我优先选择……，因为当前最紧的约束是……。但如果……，这条路径可能失效。" ${record()?'disabled':''}>${esc(s.thesis)}</textarea><div class="notice">提交后本轮判断会封存。真实历史不会被你的选择改变，也不会给你的政策打分。</div>${actionBar('下一步将揭晓真实政策与十年结果。',record()?'查看已揭晓的历史':'封存判断，揭晓历史','reveal',1,!record()&&(!s.risk||s.thesis.trim().length<8))}</section><aside class="summary-box"><h3>你的三个优先方向</h3>${round().groups.map((g,i)=>`<div class="selected-summary"><strong>${POLICIES[g].name}</strong><p>${s.picks[i]===null?'尚未选择':POLICIES[g].options[s.picks[i]][0]}</p></div>`).join('')}<p>未来不止取决于政策。记录一个可能推翻判断的条件，比给自己一个“正确答案”更有价值。</p></aside></div>`;}
function reveal(){const r=round(),g=actualGrowth();return `<section class="history-banner"><div><small>历史档案已打开 · ${r.year}—${r.year+10}</small><h2 style="margin-top:7px">${country().name}真实走过的十年</h2><p>下面是实际发生的历史，不是你的政策组合的模拟结果。</p></div><div class="range-value">${g>=0?'+':''}${g.toFixed(1)}%<small>实际人均 GDP 年均变化</small></div></section><div class="two-col"><section class="panel"><h2>历史中的选择与转折</h2>${r.events.map(([y,h,p])=>`<article class="history-event"><time>${y}</time><div><strong>${h}</strong><p>${p}</p></div></article>`).join('')}<div class="notice">${r.cost}</div>${actionBar('先把“发生了什么”与“为什么发生”分开。','比较我的判断','compare',2)}</section><aside class="summary-box"><h3>十年后的三个变化</h3>${[['人均 GDP',`${num(indicators[state.country].gdp[r.year])} → ${num(indicators[state.country].gdp[r.year+10])} 美元`],['城市化率',`${indicators[state.country].urban[r.year].toFixed(1)}% → ${indicators[state.country].urban[r.year+10].toFixed(1)}%`],['人口',`${(indicators[state.country].population[r.year]/1e6).toFixed(1)} → ${(indicators[state.country].population[r.year+10]/1e6).toFixed(1)} 百万`]].map(([h,v])=>`<div class="selected-summary"><strong>${h}</strong><p>${v}</p></div>`).join('')}<p>GDP 使用 2015 年不变美元。城市化和人口是背景变化，不能据此认定某项政策的作用。</p></aside></div>`;}
function chart(){const r=round(),d=indicators[state.country].gdp,vals=Array.from({length:11},(_,i)=>d[r.year+i]/d[r.year]*100),pred=Array.from({length:11},(_,i)=>100*Math.pow(1+record().growth/100,i)),mn=Math.floor(Math.min(...vals,...pred)/20)*20-10,mx=Math.ceil(Math.max(...vals,...pred)/20)*20+10,x=i=>48+i*48,y=v=>175-(v-mn)/(mx-mn)*145;const path=vs=>vs.map((v,i)=>`${i?'L':'M'}${x(i)},${y(v)}`).join(' ');return `<svg class="chart" viewBox="0 0 580 220" role="img" aria-label="${r.year} 至 ${r.year+10} 年实际人均 GDP 指数和你预测的平均增长轨迹，起点为 100">${[mn+(mx-mn)*.1,mn+(mx-mn)*.5,mn+(mx-mn)*.9].map(v=>`<line x1="48" x2="532" y1="${y(v)}" y2="${y(v)}" stroke="#e9edf3"/><text x="36" y="${y(v)+4}" text-anchor="end">${Math.round(v)}</text>`).join('')}<path d="${path(pred)}" fill="none" stroke="#acb6c8" stroke-width="2" stroke-dasharray="5 5"/><path d="${path(vals)}" fill="none" stroke="#365ed8" stroke-width="2.7"/>${vals.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="${i===10?4:2.2}" fill="#365ed8"/>`).join('')}${[0,5,10].map(i=>`<text x="${x(i)}" y="203" text-anchor="middle">${r.year+i}</text>`).join('')}<text x="48" y="15">起点 = 100</text></svg>`;}
function compare(){const r=round(),rec=record(),g=actualGrowth(),delta=g-rec.growth;return `<section class="panel"><div class="section-line"><h2>你的预期，与真实轨迹</h2><button class="source-btn" data-action="data">查看逐年数据</button></div><div class="comparison"><div class="compare-col"><h3>你预期的年均增长</h3><div class="range-value">${rec.growth>0?'+':''}${rec.growth.toFixed(1)}%<small>区间信心 ${rec.confidence}%</small></div><p class="small">预期区间：${(rec.growth-2).toFixed(1)}% 至 ${(rec.growth+2).toFixed(1)}%</p></div><div class="compare-col"><h3>实际发生的年均增长</h3><div class="range-value">${g>0?'+':''}${g.toFixed(1)}%<small>比预期${delta>=0?'高':'低'} ${Math.abs(delta).toFixed(1)} 个百分点</small></div><p class="small">${Math.abs(delta)<=2?'实际值落在你预先给定的区间内。':'实际值落在你预先给定的区间外。'}这不是政策得分。</p></div></div>${chart()}<div class="legend"><span>历史观测值</span><span>你的增长预期（等速示意）</span></div><p class="explain-caption">虚线仅把你预测的年均增速画成等速轨迹，不是政策效果模型，也不是对每年波动的预测。</p></section><section class="panel"><h2>选择相似，也不意味着解释相同</h2>${r.groups.map((g,i)=>`<div class="policy-group"><h3 style="font-size:14px;margin-bottom:10px">${POLICIES[g].name}</h3><div class="comparison"><div class="compare-col"><h3>你的优先方向</h3><p>${POLICIES[g].options[rec.picks[i]][0]}</p></div><div class="compare-col"><h3>真实政策概述</h3><p>${r.historyLabels[i]}</p></div></div></div>`).join('')}<div class="reason"><strong>你在揭晓前写下的理由</strong><p>${esc(rec.thesis)}</p><p class="small">当时最担心：${rec.risk}</p></div>${actionBar('结果接近，可能是判断有效，也可能是不同因素抵消。','拆解因果，修正判断','explain',3)}</section>`;}
function explain(){const r=round(),rec=record();return `<section class="panel"><h2>五种解释，不能混成一个故事</h2><p>以下是有依据的解释框架，不是对各因素贡献的精确估计。</p><div class="causal-chain">${r.chain.map((t,i)=>`${i?'<i aria-hidden="true">→</i>':''}<span>${t}</span>`).join('')}</div><p class="explain-caption">可能的机制链条。箭头表示待检验的机制，不表示已识别的因果效应。</p><div class="causes">${['结构性因素','政策选择','外部环境','运气与时点','事后归因的不确定性'].map((t,i)=>`<article class="cause"><h3><span class="cause-type"></span>${t}</h3><p>${r.causes[i]}</p></article>`).join('')}</div></section><section class="panel"><h2>带走一个更好的问题</h2><div class="reason" style="font-size:16px">${r.lesson}</div><label class="input-label" for="reflection">现在，你会修正哪条判断？还需要什么证据？ <span class="small">至少 8 个字</span></label><textarea id="reflection" maxlength="1500" placeholder="我之前忽略了……。下次遇到类似国家，我会先核实……，而不是直接复制某项政策。">${esc(session().reflection||rec.reflection||'')}</textarea><p class="field-note">你的原始判断会保留，修正内容另行记录。下一轮采用真实历史的新起点。</p>${actionBar('学习成果是更好的问题，而不是一个更高的分数。',session().round<2?'保存复盘，进入下一轮':'完成三轮，回看判断','next',4,(session().reflection||rec.reflection||'').trim().length<8)}</section>`;}
function completed(){const rs=session().records;return `<div class="round-heading"><div><div class="eyebrow">${country().name} · 三十年决策档案</div><h1>你带走的，不该是一个答案。</h1><p class="intro">三次下注、三次修正。试着把这些问题带到一个陌生国家。</p></div></div><section class="complete-card"><h2>面对下一个国家，先问这些</h2><ol class="question-list"><li>真正卡住增长的是外汇、技能、基础设施，还是国家执行能力？</li><li>政策依赖哪些已有条件？换一个国家，这些条件还存在吗？</li><li>谁承担转型的成本？这种分配安排能维持多久？</li><li>债务的币种和期限是什么？靠什么创造未来的偿付能力？</li><li>哪些变化来自外部环境？什么证据能推翻我的解释？</li></ol><div class="notice">你完成了 ${rs.length} 轮判断。它们不足以证明预测能力，更不是对现实国家的政策处方。</div>${actionBar('原始判断和修正内容已收录到本机手记。','选择下一个国家','countries')}</section><div style="margin-top:20px"><button class="secondary" data-nav="notebook">回看我的判断手记</button></div>`;}
function notebook(){const rs=Object.entries(state.countries).flatMap(([code,s])=>s.records.map(r=>({...r,code})));return `<div class="round-heading"><div><div class="eyebrow">${rs.length} 次封存的判断</div><h1>把当时的自己，留下来。</h1><p class="intro">避免事后“我早就知道”。原始理由与后来的修正分开记录。</p></div></div>${rs.length?`<div class="ledger">${rs.map(rec=>{const d=indicators[rec.code].gdp,g=(Math.pow(d[rec.year+10]/d[rec.year],.1)-1)*100;return `<article class="ledger-entry"><div class="section-line"><h3>${COUNTRIES[rec.code].name} / ${rec.year}—${rec.year+10}</h3><small>${rec.reflection?'已复盘':'待复盘'}</small></div><div class="ledger-meta"><span>预测 ${rec.growth.toFixed(1)}% / 年</span><span>实际 ${g.toFixed(1)}% / 年</span><span>±2 个百分点内的信心 ${rec.confidence}%</span></div><p><strong>当时的判断</strong>　${esc(rec.thesis)}</p><p><strong>后来修正</strong>　${esc(rec.reflection||'完成因果拆解后，在这里留下修正。')}</p><p class="small">担心的风险：${esc(rec.risk)}。单次预测偏差不能识别政策效果。</p></article>`}).join('')}</div><p class="save-note">手记仅保存在当前浏览器。清除浏览器数据会删除进度，不会跨设备同步。</p>`:`<section class="empty">${icon('note')}<h2 style="margin-top:14px">还没有封存的判断</h2><p>在历史实验中提交一次政策判断和预测，手记就会开始记录。</p><button class="primary" data-nav="lab">回到当前回合</button></section>`}`;}
function method(){return `<div class="round-heading"><div><div class="eyebrow">方法与边界</div><h1>学会推理，而不是记住赢家。</h1><p class="intro">这是一个历史决策学习工具。它不宣称计算出了国家发展的唯一公式。</p></div></div><section class="panel"><h2>六步完成一个回合</h2><div class="method-block"><h3>观察 → 判断 → 下注</h3><p>看当时的少数关键条件，选择三个政策优先方向，再记录对现实未来的增长预测、信心、风险和理由。未来数据在页面中保持封存，直到你提交判断。</p></div><div class="method-block"><h3>揭晓 → 比较 → 解释</h3><p>先看实际事件和结果，比较原始预期，再区分结构、政策、外部环境、运气与归因不确定性。每轮留下修正，下一轮从真实历史条件重新出发。</p></div><div class="method-block"><h3>为什么没有“国力分数”？</h3><p>人均 GDP 只反映部分物质产出，无法代表自由、平等、健康、生态和安全。与历史政策相似也不能证明你选得更好，更不能为政治压制或人权侵害辩护。</p></div><div class="method-block"><h3>为什么没有另一条历史曲线？</h3><p>我们没有识别出可信的政策因果参数，也没有可验证的反事实模型。因此你的选择只记录机制和取舍，不会生成看似精确的政策收益。比较页虚线只是你填写的增长预期。</p></div><div class="method-block"><h3>如何理解信心？</h3><p>你给出真实年均增长落在“预测值 ±2 个百分点”内的概率。多轮才能初步观察信心与结果的关系；三个案例不足以严格估计校准度。没有奖惩或排名。</p></div><div class="method-block"><h3>历史时点与数据口径</h3><p>“1960 年”等是该年度概述，不假装统计数据在当年年初已完整可得。人均 GDP 使用世界银行 2015 年不变美元；增长为两个端点计算的几何年均增长。教育和政策背景是定性编辑摘要，不是标准化评分。城市化定义因国家不同而异。</p></div><div class="notice">首版含韩国、阿根廷 1960–1990 和新加坡 1965–1995，共 9 轮。历史叙述是精选摘要，不能代替完整的经济史研究。外链资料可能包含尚未揭晓的后续历史。</div><div class="bottom-action"><button class="secondary" data-action="sources">查看数据来源与阅读材料</button><button class="primary" data-nav="lab">回到历史实验</button></div></section>`;}
function footer(){return `<footer class="footer"><span>基于真实历史 · 不给政策打分 · 不把相关当因果</span><button class="source-btn" data-action="sources">数据来源与口径 ${icon('book')}</button></footer>`;}
function render(focus=false){const s=session();document.querySelector('#app').innerHTML=header()+(view==='lab'?(s.complete?completed():roundHeading()+[observe,choose,bet,reveal,compare,explain][s.step]()):view==='notebook'?notebook():method())+footer()+'</main></div>';if(focus){window.scrollTo(0,0);document.querySelector('#main').focus({preventScroll:true});}}
function openDialog(title,html){const d=document.querySelector('#dialog');d.innerHTML=`<div class="dialog-top"><h2 id="dialog-title">${title}</h2><button class="close" data-action="close" aria-label="关闭弹窗">×</button></div><div class="dialog-body">${html}</div>`;d.showModal();}
function modalCountries(){openDialog('选择一份国家档案',`<p class="muted">三个不同的起点。只展示起始条件，不提前透露结局。切换会保留当前进度。</p><div class="country-grid">${Object.entries(COUNTRIES).map(([c,d])=>`<button class="country-choice" data-country="${c}"><span class="country-code">${c}</span><div><h3>${d.name} <span class="muted" style="font-weight:400">/ ${d.start}</span></h3><p>${d.description}</p></div><small>${state.countries[c].complete?'已完成':state.countries[c].records.length?'继续探索':'3 个十年回合'}</small></button>`).join('')}</div><p class="save-note">首次可以从韩国开始；熟悉后换一个约束不同的国家，检验你的直觉能否迁移。</p>`);}
function modalContext(){openDialog(`${country().name} · ${round().year} 年国情档案`,`<p class="muted">按需阅读。以下仅包含这个决策时点已发生的条件。定性描述是历史摘要，未量化的项目不填入伪精确数值。</p><div class="context-grid">${Object.entries(round().context).map(([k,v])=>`<section><h3>${k}</h3><p>${v}</p></section>`).join('')}</div>`);}
function modalSources(){openDialog('数据来源与阅读材料',`<p class="source-disclaimer">外部资料可能透露后续历史。量化数据已取得快照；历史叙述为编辑整理，参考书目不等于对每条因果解释的实证证明。</p><div class="source-item"><h3>本次数据快照</h3><p>WDI 人均 GDP 与城市化：来源更新于 ${indicators.KOR.updated}，本工具获取于 2026-10-05。人口采用 datasets/population 的世界银行镜像；不同批次可能有修订。精确观测值可在揭晓后的比较页查看。</p><p>增长公式：(期末人均 GDP ÷ 期初人均 GDP)^(1/10) − 1。价格不变不等于购买力平价，不能据此直接比较三国生活水平。</p></div>${SOURCES.map(s=>`<article class="source-item"><small>${s.kind}</small><p><a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.name}</a></p><p>${s.note}</p></article>`).join('')}<p class="save-note">历史参考网站在本次构建中存在访问限制，未做逐页核验；关键事件采用通行历史叙述，仍应对照原始文献和不同研究观点。</p>`);}
function modalData(){if(!record())return;const r=round(),d=indicators[state.country];openDialog('逐年观测值与计算口径',`<p class="muted">世界银行 WDI。人均 GDP 为 2015 年不变美元；每年为真实观测，图表未用插值补齐。</p><table class="stat-table"><thead><tr><th>年份</th><th>人均 GDP</th><th>城市化率</th></tr></thead><tbody>${Array.from({length:11},(_,i)=>r.year+i).map(y=>`<tr><td>${y}</td><td>${d.gdp[y].toFixed(2)}</td><td>${d.urban[y].toFixed(2)}%</td></tr>`).join('')}</tbody></table><p class="save-note">年均增长 = (${d.gdp[r.year+10].toFixed(2)} ÷ ${d.gdp[r.year].toFixed(2)})^(1/10) − 1 = ${actualGrowth().toFixed(2)}%。</p>`);}
function submit(){const s=session();if(record()){setStep(3);return;}if(s.picks.some(x=>x===null)||!s.risk||s.thesis.trim().length<8){toast('请完成三项选择、风险与判断理由。');return;}s.records.push({year:round().year,picks:[...s.picks],growth:Number(s.growth),confidence:s.confidence,risk:s.risk,thesis:s.thesis.trim(),reflection:'',submittedAt:new Date().toISOString()});s.step=3;save();render(true);}
function next(){const s=session(),rec=record();if(!rec||s.reflection.trim().length<8)return;rec.reflection=s.reflection.trim();if(s.round===2)s.complete=true;else Object.assign(s,{round:s.round+1,step:0,picks:[null,null,null],growth:4,confidence:70,risk:null,thesis:'',reflection:''});save();render(true);toast(s.complete?'三轮判断与修正已保存':'复盘已保存，进入新的历史起点');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const s=session();if(b.dataset.nav){navigate(b.dataset.nav);return;}if(b.dataset.step!==undefined){setStep(Number(b.dataset.step));return;}if(b.dataset.pick!==undefined){if(record())return;const [i,j]=b.dataset.pick.split(',').map(Number);s.picks[i]=j;save();const sy=window.scrollY;render();window.scrollTo(0,sy);document.querySelector(`[data-pick="${i},${j}"]`).focus({preventScroll:true});return;}if(b.dataset.confidence){if(record())return;s.confidence=Number(b.dataset.confidence);save();document.querySelectorAll('[data-confidence]').forEach(x=>{x.classList.toggle('selected',x.dataset.confidence===b.dataset.confidence);x.setAttribute('aria-pressed',x.dataset.confidence===b.dataset.confidence)});return;}if(b.dataset.risk){if(record())return;s.risk=b.dataset.risk;save();document.querySelectorAll('[data-risk]').forEach(x=>{x.classList.toggle('selected',x.dataset.risk===b.dataset.risk);x.setAttribute('aria-pressed',x.dataset.risk===b.dataset.risk)});updateSubmit();return;}if(b.dataset.country){state.country=b.dataset.country;view='lab';save();document.querySelector('#dialog').close();render(true);return;}const a=b.dataset.action;if(a==='countries')modalCountries();else if(a==='context')modalContext();else if(a==='sources')modalSources();else if(a==='data')modalData();else if(a==='close')document.querySelector('#dialog').close();else if(a==='choose')setStep(1);else if(a==='bet'){if(!s.picks.includes(null))setStep(2);}else if(a==='reveal')submit();else if(a==='compare')setStep(4);else if(a==='explain')setStep(5);else if(a==='next')next();});
function updateSubmit(){const b=document.querySelector('[data-action="reveal"]');if(b&&!record())b.disabled=!session().risk||session().thesis.trim().length<8;}
document.addEventListener('input',e=>{const t=e.target,s=session();if(t.id==='growth'&&!record()){s.growth=Number(t.value);document.querySelector('#growth-value').textContent=s.growth.toFixed(1)+'%';}else if(t.id==='thesis'&&!record()){s.thesis=t.value;updateSubmit();}else if(t.id==='reflection'){s.reflection=t.value;const b=document.querySelector('[data-action="next"]');if(b)b.disabled=s.reflection.trim().length<8;}else return;save();});
document.addEventListener('keydown',e=>{const b=e.target.closest('[data-pick]');if(!b||record()||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const [i,j]=b.dataset.pick.split(',').map(Number);document.querySelector(`[data-pick="${i},${(j+(['ArrowLeft','ArrowUp'].includes(e.key)?2:1))%3}"]`).click();});
document.querySelector('#dialog').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close();}});
function registerAgentTools(){if(!document.modelContext?.registerTool)return;try{Promise.resolve(document.modelContext.registerTool({name:'read_current_historical_brief',title:'读取当前历史条件',description:'读取当前国家和回合可见的条件；不会提前返回未来事件或结果。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).length)throw new Error('此工具不接受参数');return {country:country().name,year:round().year,step:STEPS[session().step],constraints:round().evidence.map(x=>({title:x[0],detail:x[1]})),context:round().context,revealed:!!record()};}})).catch(()=>{});}catch(e){}}
fetch('indicators.json').then(r=>{if(!r.ok)throw Error('data');return r.json();}).then(d=>{indicators=d;render();registerAgentTools();}).catch(()=>{document.querySelector('#app').innerHTML='<main><h1>历史数据暂时未能载入</h1><p>请检查网络连接后重新加载。本机已保存的判断不会被清除。</p><button class="primary" onclick="location.reload()">重新加载</button></main>';});
